sky:
precision highp float;
uniform vec2 u_res;
uniform float u_t;
uniform vec3 u_main;
uniform vec3 u_low;
uniform vec3 u_mid;
uniform vec3 u_high;
uniform float u_wind;   // wind speed
uniform float u_warp;   // warp power
uniform float u_nscale; // noise scale
uniform sampler2D u_noise;

const float FBM_STRENGTH = 0.912;
const float BLUR_RADIUS = 1.2673;
const float ZOOM = 0.3971;
const float GRAIN_SCALE = 2.5;
const float GRAIN_STRENGTH = 0.014;

vec3 burn(vec3 base, vec3 blend, float op){
  return max(base + blend - vec3(1.0), vec3(0.0))*op + base*(1.0-op);
}
float rand2(vec2 n){ return fract(sin(dot(n, vec2(12.9898, 4.1414)))*43758.5453); }
float noise2(vec2 p){
  vec2 ip = floor(p); vec2 u = fract(p);
  u = u*u*(3.0-2.0*u);
  float m = mix(mix(rand2(ip), rand2(ip+vec2(1.,0.)), u.x), mix(rand2(ip+vec2(0.,1.)), rand2(ip+vec2(1.,1.)), u.x), u.y);
  return m*m;
}
float fbm4(vec2 x){
  float v = 0.0; float a = 0.5;
  vec2 shift = vec2(100.0);
  mat2 rot = mat2(cos(0.5), sin(0.5), -sin(0.5), cos(0.5));
  for (int i = 0; i < 4; i++) { v += a*noise2(x); x = rot*x*2.0 + shift; a *= 0.5; }
  return v;
}
vec4 permute4(vec4 x){ return mod((x*34.0 + 1.0)*x, 289.0); }
vec4 tisqrt(vec4 r){ return 1.79284291400159 - 0.85373472095314*r; }
vec3 fade3(vec3 t){ return t*t*t*(t*(t*6.0-15.0)+10.0); }
float cnoise(vec3 P){
  vec3 Pi0 = floor(P); vec3 Pi1 = Pi0 + vec3(1.0);
  Pi0 = mod(Pi0, 289.0); Pi1 = mod(Pi1, 289.0);
  vec3 Pf0 = fract(P); vec3 Pf1 = Pf0 - vec3(1.0);
  vec4 ix = vec4(Pi0.x, Pi1.x, Pi0.x, Pi1.x);
  vec4 iy = vec4(Pi0.yy, Pi1.yy);
  vec4 iz0 = vec4(Pi0.z); vec4 iz1 = vec4(Pi1.z);
  vec4 ixy = permute4(permute4(ix) + iy);
  vec4 ixy0 = permute4(ixy + iz0); vec4 ixy1 = permute4(ixy + iz1);
  vec4 gx0 = ixy0/7.0; vec4 gy0 = fract(floor(gx0)/7.0) - 0.5; gx0 = fract(gx0);
  vec4 gz0 = vec4(0.5) - abs(gx0) - abs(gy0); vec4 sz0 = step(gz0, vec4(0.0));
  gx0 -= sz0*(step(vec4(0.0), gx0) - 0.5); gy0 -= sz0*(step(vec4(0.0), gy0) - 0.5);
  vec4 gx1 = ixy1/7.0; vec4 gy1 = fract(floor(gx1)/7.0) - 0.5; gx1 = fract(gx1);
  vec4 gz1 = vec4(0.5) - abs(gx1) - abs(gy1); vec4 sz1 = step(gz1, vec4(0.0));
  gx1 -= sz1*(step(vec4(0.0), gx1) - 0.5); gy1 -= sz1*(step(vec4(0.0), gy1) - 0.5);
  vec3 g000 = vec3(gx0.x, gy0.x, gz0.x); vec3 g100 = vec3(gx0.y, gy0.y, gz0.y);
  vec3 g010 = vec3(gx0.z, gy0.z, gz0.z); vec3 g110 = vec3(gx0.w, gy0.w, gz0.w);
  vec3 g001 = vec3(gx1.x, gy1.x, gz1.x); vec3 g101 = vec3(gx1.y, gy1.y, gz1.y);
  vec3 g011 = vec3(gx1.z, gy1.z, gz1.z); vec3 g111 = vec3(gx1.w, gy1.w, gz1.w);
  vec4 n0 = tisqrt(vec4(dot(g000,g000), dot(g010,g010), dot(g100,g100), dot(g110,g110)));
  g000 *= n0.x; g010 *= n0.y; g100 *= n0.z; g110 *= n0.w;
  vec4 n1 = tisqrt(vec4(dot(g001,g001), dot(g011,g011), dot(g101,g101), dot(g111,g111)));
  g001 *= n1.x; g011 *= n1.y; g101 *= n1.z; g111 *= n1.w;
  float n000 = dot(g000, Pf0); float n100 = dot(g100, vec3(Pf1.x, Pf0.yz));
  float n010 = dot(g010, vec3(Pf0.x, Pf1.y, Pf0.z)); float n110 = dot(g110, vec3(Pf1.xy, Pf0.z));
  float n001 = dot(g001, vec3(Pf0.xy, Pf1.z)); float n101 = dot(g101, vec3(Pf1.x, Pf0.y, Pf1.z));
  float n011 = dot(g011, vec3(Pf0.x, Pf1.yz)); float n111 = dot(g111, Pf1);
  vec3 fx = fade3(Pf0);
  vec4 nz = mix(vec4(n000,n100,n010,n110), vec4(n001,n101,n011,n111), fx.z);
  vec2 ny = mix(nz.xy, nz.zw, fx.y);
  return 2.2*mix(ny.x, ny.y, fx.x);
}
uniform vec2 u_dirv; // (cos, sin) of the direction quarter-turn
void main(){
  vec2 st = gl_FragCoord.xy/u_res - 0.5;
  st.x *= u_res.x/u_res.y;
  st = mat2(u_dirv.x, u_dirv.y, -u_dirv.y, u_dirv.x)*st;
  float time = u_t*0.85;
  vec2 uv = st*(1.0/(2.0*ZOOM)) + 0.5;
  // gl_FragCoord runs bottom-up, so the source's y flip is already this way up
  float noiseX = cnoise(vec3(uv*u_nscale + vec2(0.0, 74.8572), time*0.3));
  float noiseY = cnoise(vec3(uv*u_nscale + vec2(203.91282, 10.0), time*0.3));
  uv += vec2(noiseX*2.0, noiseY)*u_warp;
  float noiseA = cnoise(vec3(uv*18.0 + vec2(344.91282, 0.0), time*0.3))
               + cnoise(vec3(uv*39.6 + vec2(723.937, 0.0), time*0.4))*0.5;
  uv += noiseA*0.02;
  uv.y -= 0.09;
  float xf = (sin(time) + 1.0)*0.5;
  vec2 texUv = uv*GRAIN_SCALE;
  float d0 = mix(texture2D(u_noise, texUv).r - 0.5, texture2D(u_noise, vec2(texUv.x, 1.0-texUv.y)).g - 0.5, xf)*GRAIN_STRENGTH;
  texUv += vec2(63.861, 368.937);
  float d1 = mix(texture2D(u_noise, texUv).r - 0.5, texture2D(u_noise, vec2(texUv.x, 1.0-texUv.y)).g - 0.5, xf)*GRAIN_STRENGTH;
  texUv += vec2(453.163, 1649.808);
  float d3 = mix(texture2D(u_noise, texUv).r - 0.5, texture2D(u_noise, vec2(texUv.x, 1.0-texUv.y)).g - 0.5, xf)*GRAIN_STRENGTH;
  uv += d0;
  vec2 stF = uv*u_nscale;
  vec2 q = vec2(fbm4(stF*0.5 + u_wind*time));
  vec2 r = vec2(fbm4(stF + q + vec2(0.3, 9.2) + 0.15*time), fbm4(stF + q + vec2(8.3, 0.8) + 0.126*time));
  float fv = fbm4(stF + r - q);
  float full = (fv + 0.6*fv*fv + 0.7*fv + 0.5)*0.5;
  full = pow(full, 0.55)*FBM_STRENGTH;
  float blurR = BLUR_RADIUS*1.5;
  vec2 uvA = uv + vec2((full-0.5)*1.2) + vec2(0.0, 0.025) + d0;
  float snA = noise2(uvA*2.0 + vec2(0.0, time*0.5))*3.0;
  float lA = pow(smoothstep(snA - 1.2*blurR, snA + 1.2*blurR, (uvA.y - 0.5)*5.0 + 0.5), 0.8);
  vec2 uvB = uv + vec2((full-0.5)*0.85) + vec2(0.0, 0.025) + d1;
  float snB = noise2(uvB*4.0 + vec2(293.0, time))*2.8;
  float lB = pow(smoothstep(snB - 0.9*blurR, snB + 0.9*blurR, (uvB.y - 0.6)*5.0 + 0.5), 0.9);
  vec2 uvC = uv + vec2((full-0.5)*1.1) + d3;
  float snC = noise2(uvC*6.0 + vec2(153.0, time*1.2))*2.6;
  float lC = smoothstep(snC - 0.7*blurR, snC + 0.7*blurR, (uvC.y - 0.9)*6.0 + 0.5);
  vec3 col = burn(u_main, u_low, 1.0 - lA);
  col = burn(col, mix(u_main, u_mid, 1.0 - lB), lA);
  col = mix(col, mix(u_main, u_high, 1.0 - lC), lA*lB);
  gl_FragColor = vec4(col, 1.0);
}

aurora:
precision highp float;
uniform vec2 u_res;
uniform float u_t;
uniform vec3 u_deep;
uniform vec3 u_horizon;
uniform vec3 u_glow;
uniform vec3 u_rim;
uniform float u_drift;
uniform float u_fold;
uniform float u_freq;
uniform vec2 u_dirv;

float hash21(vec2 p){ return fract(sin(dot(p, vec2(127.1, 311.7)))*43758.5453123); }
float noise2(vec2 p){
  vec2 ip = floor(p); vec2 u = fract(p);
  u = u*u*(3.0-2.0*u);
  return mix(mix(hash21(ip), hash21(ip+vec2(1.0,0.0)), u.x), mix(hash21(ip+vec2(0.0,1.0)), hash21(ip+vec2(1.0,1.0)), u.x), u.y);
}
float fbm3(vec2 p){
  float v = 0.0; float a = 0.5;
  mat2 rot = mat2(cos(0.5), sin(0.5), -sin(0.5), cos(0.5));
  for (int i = 0; i < 3; i++) { v += a*noise2(p); p = rot*p*2.02 + vec2(37.0, 17.0); a *= 0.5; }
  return v;
}
float fbm2(vec2 p){
  float v = 0.0; float a = 0.5;
  mat2 rot = mat2(cos(0.5), sin(0.5), -sin(0.5), cos(0.5));
  for (int i = 0; i < 2; i++) { v += a*noise2(p); p = rot*p*2.02 + vec2(37.0, 17.0); a *= 0.5; }
  return v;
}
void main(){
  vec2 st = gl_FragCoord.xy/u_res - 0.5;
  st.x *= u_res.x/u_res.y;
  st = mat2(u_dirv.x, u_dirv.y, -u_dirv.y, u_dirv.x)*st;
  float x = st.x;
  float hv = st.y + 0.5; // 0 at the horizon foot, 1 at the zenith
  float time = u_t*0.35;
  // night everywhere: the ribbon is the only bright object. Just a weak
  // pool of horizon light at the very foot of the frame
  float hzp = 1.0 - smoothstep(0.0, 0.22, hv);
  vec3 sky = mix(u_deep, u_horizon, hzp*hzp*0.18);
  // how far the ribbon swoops across the frame: the Fold dial's main job
  float amp = 0.05 + u_fold*0.22;
  // one coherent field-aligned lean for every ray, breathing slowly
  float tiltG = (noise2(vec2(time*0.11, 71.3)) - 0.5)*0.9;
  // ONE spine, computed once: the companion strand is strictly parallel
  // (offset only) — independent phases enclose dark pockets between strands
  float tiltR = (noise2(vec2(time*0.07, 41.7)) - 0.5)*0.35;
  float wob = (fbm2(vec2(x*u_freq*0.6 + time*u_drift*0.3, time*0.09)) - 0.5)*1.6;
  float ph = time*u_drift*0.7 + wob;
  // freq is squared so the Scale dial genuinely commands the wave count;
  // the second harmonic breaks the metronome sine into uneven crests
  float sf = u_freq*u_freq*0.65;
  float th = x*sf + ph;
  float th2 = (x + 0.012)*sf + ph;
  float wv = 0.5 + 0.5*(0.78*sin(th) + 0.22*sin(2.0*th + 2.1));
  float wv2 = 0.5 + 0.5*(0.78*sin(th2) + 0.22*sin(2.0*th2 + 2.1));
  float wave = (wv - 0.5)*2.0 + x*tiltR;
  float slope = abs(wv2 - wv)/0.012;
  vec3 aur = vec3(0.0);
  float cover = 0.0;
  for (int i = 0; i < 2; i++) {
    float fi = float(i);
    float freq = u_freq*(1.0 + fi*0.15);
    float drift = u_drift*(0.75 + fi*0.25);
    // depth meander: near stretches are tall and bright, far ones compact
    float nr = smoothstep(0.35, 0.65, fbm2(vec2(x*freq*0.5 + time*drift*0.4 + fi*21.3, fi*3.77 + time*0.07)));
    // the wig detail only textures the rays; the spine stays SMOOTH —
    // wavy, never kinked
    float wig = fbm3(vec2(x*freq*2.6 + time*drift + fi*3.7, fi*7.31 + time*0.13)) - 0.5;
    float spine = 0.31 + fi*0.12 + amp*wave;
    // a ribbon keeps constant PERPENDICULAR thickness: the vertical
    // cross-section widens where the spine runs steep, and the edge-on fold
    // stacks the line of sight into a bright knot
    float m = slope*amp*2.0;
    float widen = sqrt(1.0 + min(m*m*2.5, 5.0));
    float s = (0.17 + u_fold*0.07)*(0.7 + nr*0.85)*(1.0 - fi*0.2)*widen;
    float knotK = 1.0 + (0.25 + 1.15*u_fold)*smoothstep(1.1, 3.0, slope*amp*6.0);
    // the life of the aurora: brightness SURGES travel along the band,
    // the way real displays ripple lengthwise
    float surge = 0.78 + 0.22*noise2(vec2(x*1.1 - time*1.3, 5.5 + fi*2.2));
    float L = (0.6 + 0.4*nr)*knotK*surge;
    float u = (hv - spine)/s; // ribbon-local altitude
    // field-aligned rays: global lean + a gentle perspective fan, x-only
    // octaves (a rotating fbm domain cross-hatches)
    float xr = x*freq*(4.5 + 2.0*nr) + wig*2.2 + time*drift*1.6 + max(u, 0.0)*s*(tiltG + x*0.22)*3.0;
    float yr = hv*0.8 + fi*9.13;
    float v = 0.5*noise2(vec2(xr, yr)) + 0.28*noise2(vec2(xr*2.7 + 13.7, yr*1.7 + 5.2)) + 0.14*noise2(vec2(xr*6.1 + 31.9, yr*2.3 + 11.4)) + 0.08*noise2(vec2(xr*12.3 + 57.1, yr*2.9 + 23.7));
    // quiet arc = homogeneous glow; storm = hard pickets. Fold morphs the gate
    float soft = 0.55 + 0.45*smoothstep(0.3, 0.7, v);
    float hard = 0.1 + 0.9*smoothstep(0.38, 0.6, v);
    // low-frequency bundles: whole folds brighten, night shows between them
    float bn = noise2(vec2(x*freq*1.4 + time*drift*0.8 + fi*17.3, fi*4.77));
    // fast per-ray twinkle: single ray bundles blink in and out
    float flick = 0.85 + 0.15*noise2(vec2(x*freq*3.1 + time*2.8, 7.7 + fi*3.0));
    float rayK = mix(soft, hard, u_fold)*(0.45 + 0.55*smoothstep(0.26, 0.72, bn))*flick;
    float kBody = 1.0 - 0.7*fi;
    // NO lines anywhere: the whole aurora is one soft BEAM. An asymmetric
    // gaussian around the spine — tighter below, a long fade above — so
    // the light melts into the night in every direction
    float d = u - 0.15;
    float sig = d < 0.0 ? 0.26 : 0.55;
    float beam = exp(-(d*d)/(2.0*sig*sig));
    float body = beam*(0.28 + 0.72*rayK);
    float k = kBody*L;
    // colour lives inside the beam: the lightest tone burns the core, the
    // body is the glow tone, the top thins toward deep, and the lower tail
    // cools toward the horizon tone. All blends, no bands
    float peakK = beam*beam*0.75;
    vec3 gcol = mix(u_glow, u_rim, peakK);
    gcol = mix(gcol, u_deep, smoothstep(0.35, 1.05, u)*0.5);
    gcol = mix(gcol, u_horizon, (1.0 - smoothstep(-0.38, -0.12, d))*0.3);
    // intensity rides the storminess: quiet arcs soft, storms blazing
    float gB = body*(0.88 + u_fold*0.36)*k;
    aur += gcol*gB;
    cover += gB;
  }
  // hash-grid stars: kept clear of the horizon, the curtains and any
  // daylight-bright palette
  vec2 gp = vec2(x, hv)*60.0;
  vec2 cell = floor(gp);
  float hct = hash21(cell);
  float starI = 0.0;
  if (hct > 0.96) {
    vec2 spos = vec2(hash21(cell + 11.3), hash21(cell + 27.7))*0.6 + 0.2;
    float r = length(fract(gp) - spos);
    float tw = 0.6 + 0.4*sin(u_t*(2.0 + hct*6.0) + hct*100.0);
    float bmag = (hct - 0.96)/0.04;
    starI = pow(max(0.0, 1.0 - r/0.14), 4.0)*(0.3 + 0.7*bmag)*tw;
    starI *= smoothstep(0.03, 0.12, hv)*clamp(1.0 - cover*2.2, 0.0, 1.0);
    float skyL = dot(sky, vec3(0.299, 0.587, 0.114));
    starI *= 1.0 - smoothstep(0.25, 0.6, skyL);
  }
  vec3 col = clamp(sky + aur + vec3(0.95, 0.97, 1.0)*starI, 0.0, 1.0);
  gl_FragColor = vec4(col, 1.0);
}

silk:
precision highp float;
uniform vec2 u_res;
uniform float u_angle,u_folds,u_drape,u_tension,u_depth,u_zoom,u_phase,u_time;
uniform float u_sheen,u_thread,u_glow;
uniform vec3 u_light;
uniform sampler2D u_palette;

vec2 clothCoordinates(vec2 xy) {
  float ca=cos(u_angle), sa=sin(u_angle);
  float u=(xy.x*ca+xy.y*sa)/u_zoom;
  float v=(-xy.x*sa+xy.y*ca)/u_zoom;
  float ph=u_phase, t=u_time;
  float a=0.35+u_drape*0.3000;
  float wu=a*sin(1.9*v+0.6*u+ph+t)+0.0500*sin(4.1*v-1.3*u+ph*0.7-t*0.6);
  float wv=a*0.6*sin(1.7*u-0.5*v+ph*1.3-t*0.8)+0.0500*sin(3.7*u+1.1*v+ph*0.4+t*0.5);
  u+=wu; v+=wv;
  float pull=(v+0.45)*1.7;
  float spread=1.0-u_tension*0.5*exp(-pull*pull);
  return vec2(((u+0.2)/spread-0.2)*u_folds,v);
}
float cloth(vec2 xy) {
  const float TAU=6.28318530718;
  vec2 coord=clothCoordinates(xy);
  float lane0=coord.x,v=coord.y,ph=u_phase;
  float lane=lane0+0.4500*sin(lane0*0.53+v*0.7+ph)+0.1*sin(lane0*1.31-v*1.1+ph*0.6+u_time*0.5);
  float lp=lane*0.3500;
  float rolled=lp+0.0500*sin(TAU*lp+ph*0.4);
  float amp=0.6+0.4000*sin(lane*0.71+v*0.9+ph*1.3);
  float along=0.8+0.2*sin(v*2.4+lane*0.4+u_time*0.3);
  float h=amp*along*(0.5+0.5*cos(TAU*rolled));
  float mask=0.5+0.5*sin(lane*0.37+v*1.7+ph*0.8);
  h+=u_tension*0.0300*mask*(0.5+0.5*cos(TAU*(lp*2.6+0.25*sin(v*2.1+ph))));
  h+=u_drape*0.6000*sin(lane/u_folds*2.0+v*1.3+ph);
  return u_depth*(0.42/sqrt(u_folds))*h;
}
vec3 pal(float t) { return texture2D(u_palette,vec2(clamp(t,0.0,1.0)*0.99609375+0.001953125,0.5)).rgb; }
void main(){
  float aspect=u_res.x/u_res.y;
  float fit=min(1.0,1.6/aspect);
  vec2 p=(vec2(gl_FragCoord.x/u_res.x,1.0-gl_FragCoord.y/u_res.y)-0.5)*vec2(aspect,1.0)*fit;
  float e=0.001;
  float h=cloth(p);
  vec3 N=normalize(vec3(-(cloth(p+vec2(e,0))-cloth(p-vec2(e,0)))/(2.0*e),-(cloth(p+vec2(0,e))-cloth(p-vec2(0,e)))/(2.0*e),1));
  // across-fold direction: the gradient of the lane coordinate
  float dux=clothCoordinates(p+vec2(e,0)).x-clothCoordinates(p-vec2(e,0)).x;
  float duy=clothCoordinates(p+vec2(0,e)).x-clothCoordinates(p-vec2(0,e)).x;
  vec2 across=normalize(vec2(dux,duy)+1e-6);
  // ridge curvature across the fold: positive on a crest, negative in a groove
  float e2=0.012;
  float curv=-(cloth(p+across*e2)+cloth(p-across*e2)-2.0*h)/(e2*e2);
  vec3 L=u_light, V=vec3(0,0,1), H=normalize(L+V);
  float shadow=1.0;
  for(int i=1;i<=10;i++) {
    float d=float(i)*0.022;
    float clearance=h+L.z*d-cloth(p+L.xy*d);
    shadow=min(shadow,clamp(0.6+clearance/(d*0.45),0.0,1.0));
  }
  float cavity=max(0.0,(cloth(p+vec2(0.03,0))+cloth(p-vec2(0.03,0))+cloth(p+vec2(0,0.03))+cloth(p-vec2(0,0.03)))*0.25-h);
  float ao=exp(-cavity*16.0);
  float nl=dot(N,L);
  float wrap=clamp((nl+0.4200)/(1.0+0.4200),0.0,1.0);
  wrap=wrap*wrap*(3.0-2.0*wrap);
  float diffuse=(0.1200+(1.0-0.1200)*wrap*shadow)*ao;
  // crest line: curvature thresholded with a crisp edge, brighter where the key reaches
  float scale=0.0550*mix(1.4,0.7,u_sheen);
  float cn=curv*scale;
  float crest=smoothstep(0.35,0.35+0.4500,cn);
  crest*=smoothstep(-0.15,0.45,nl)*shadow;
  // the gleam travels: it catches along some of the ridge, not the whole length
  vec2 fibre=clothCoordinates(p);
  crest*=0.55+0.45*sin(fibre.y*3.1+fibre.x*0.35+u_phase*0.9+u_time*0.4);
  // a thin crisp core on the exact ridge, inside the soft gleam
  float core=smoothstep(0.72,0.9,cn)*smoothstep(-0.15,0.45,nl)*shadow;
  // broad flank glow
  float nh=max(dot(N,H),0.0);
  float flank=pow(nh,6.0000)*shadow;
  float sheen=0.8000*crest+0.3000*core+0.4000*flank;
  float rim=0.2000*pow(1.0-max(N.z,0.0),2.5)*(1.0-wrap);
  // satin threads: fine lines running along the folds at a fixed device-pixel
  // period, so they stay crisp and never alias; Threads sets their strength
  float pixel=fit/u_res.y;
  float weave=sin(6.2831853*dot(p,across)/(pixel*3.0000)+fibre.y*6.0);
  weave*=0.7+0.3*sin(fibre.x*1.9+fibre.y*3.0+u_phase);
  diffuse*=1.0+weave*u_thread*0.0350;
  sheen*=1.0+weave*u_thread*0.0350*1.5;
  float x=diffuse*1.0500;
  float tone=clamp((x*(2.51*x+0.03))/(x*(2.43*x+0.59)+0.14),0.0,1.0);
  tone=pow(tone,1.2000)*0.5600;
  vec3 body=pal(tone);
  float luma=dot(body,vec3(0.2126,0.7152,0.0722));
  body=clamp(mix(vec3(luma),body,1.2200),0.0,1.0);
  vec3 color=mix(body,pal(0.86),clamp(rim,0.0,1.0));
  vec3 sheenColor=mix(pal(0.97),vec3(1.0),0.5500);
  float gain=1.7000*(0.7+u_glow*0.9);
  color=mix(color,sheenColor,1.0-exp(-sheen*gain));
  float dither=fract(sin(dot(gl_FragCoord.xy,vec2(12.9898,78.233)))*43758.5453)-0.5;
  gl_FragColor=vec4(color+dither/255.0,1);
}
